// Year 8 English literature, part 2: fifteen more verbatim extracts (Dickens, the Brontës,
// Austen, Stevenson, Jack London, O. Henry, Shakespeare, Blake, Rossetti, Kipling, Shelley,
// Keats and Darwin; see passages2.json and scratchpad/extract-y8b.mjs), plus two skills topics:
// reading an unseen poem and writing a literature essay. Every passage topic has auto-marked
// questions and a written answer that a grown-up marks.

import { readFileSync } from 'node:fs';

const PASSAGES = JSON.parse(readFileSync(new URL('./passages2.json', import.meta.url), 'utf8'));
// context notes must not contain brackets: speed reading strips the note by its closing bracket
const X = (key, context) => ({ passage: `(${context})\n\n` + PASSAGES[key].passage, passageSource: PASSAGES[key].passageSource });
const fact = (id, topic, prompt, answer, distractors, explain, extra = {}) => ({ id: `english.l2.${id}`, topic: `english.${topic}`, kind: 'fact', prompt, answer, distractors, explain, ...extra });
const mcq = (id, topic, prompt, options, explain, extra = {}) => ({
  id: `english.l2.${id}`, topic: `english.${topic}`, kind: 'mcq', prompt,
  options: options.map(([text, correct, feedback]) => ({ text, correct: !!correct, feedback })), explain, ...extra,
});
const order = (id, topic, prompt, items, explain, extra = {}) => ({ id: `english.l2.${id}`, topic: `english.${topic}`, kind: 'order', prompt, items, labels: null, explain, ...extra });
const written = (id, topic, prompt, hints, model, extra = {}) => ({ id: `english.l2.${id}`, topic: `english.${topic}`, kind: 'written', prompt, hints, model, words: [60, 250], ...extra });
const C = { formats: ['choice'] };

const SCROOGE = X('scrooge', 'Scrooge’s business partner, Jacob Marley, has been dead for seven years. This is how Dickens first describes Scrooge himself.');
const MORE = X('more', 'Oliver, an orphan of nine, lives in a workhouse, where the poor were given shelter and very little food in return for hard work. Dickens wrote partly to attack the new Poor Law of 1834.');
const REDROOM = X('redroom', 'Jane, a ten-year-old orphan, lives with her cruel aunt, Mrs Reed. After fighting back against her bullying cousin John, she is locked in the red-room as a punishment. She tells the story as an adult, looking back.');
const CATHERINE = X('catherine', 'Lady Catherine de Bourgh, a rich and proud aristocrat, has heard that her nephew Mr Darcy may propose to Elizabeth Bennet, whose family has less money and fewer grand connections. She has arrived uninvited to stop it.');
const PEW = X('pew', 'Jim Hawkins helps run his family’s inn, the Admiral Benbow. An old sea captain staying there lives in fear of other sailors coming to find him. Jim’s father has just died. The visitor in this extract is a blind man called Pew.');
const CLUB = X('club', 'Buck, a big, much-loved pet dog, has been stolen from his home in California and sold. A man in a red sweater has just beaten him with a club to break his spirit.');
const MAGI = X('magi', 'Della and Jim are a young married couple in New York with very little money. Each owns one treasure: Jim’s gold watch and Della’s long, beautiful hair. Without telling Jim, Della has had her hair cut off and sold it to buy him a present.');
const ANTONY = X('antony', 'Julius Caesar has been murdered by a group of senators led by Brutus, who claim Caesar was too ambitious and would have made himself king. Brutus has let Mark Antony, Caesar’s friend, speak at the funeral, as long as he does not blame the killers.');
const TITANIA = X('titania', 'Titania, queen of the fairies, has quarrelled with her husband Oberon, the fairy king. She tells him what their argument has done to the human world.');
const BLAKE = X('blake', 'William Blake published Songs of Experience in 1794. Its poems look at the darker side of the world. “The Tiger” asks what kind of creator could make such a fearful creature; in “London” the speaker walks through the city streets.');
const ROSSETTI = X('rossetti', 'Christina Rossetti, 1830–94, was one of the great Victorian poets. “Remember” is a sonnet spoken to someone the speaker loves; “A Birthday” celebrates love arriving.');
const IF = X('if', 'Kipling’s poem, published in 1910, is addressed to “my son”, but its advice is for any young reader. In a BBC poll in 1995 it was voted Britain’s favourite poem.');
const ANCIENT = X('ancient', 'Two Romantic sonnets about the ancient world. In “Ozymandias” a traveller describes the ruins of a statue of a mighty king of Egypt: Ozymandias is the Greek name for the pharaoh Ramesses II. In the second poem Keats describes reading Homer for the first time, in George Chapman’s translation of 1616.');
const GALAPAGOS = X('galapagos', 'In 1835 the young Charles Darwin visited the Galápagos Islands in the Pacific during a five-year voyage on HMS Beagle. What he noticed there later helped him to develop his theory of evolution by natural selection.');
const WINDOW = X('window', 'Mr Lockwood, a visitor, is spending the night at Wuthering Heights, a lonely farmhouse on the Yorkshire moors. Before sleeping he found the names Catherine Earnshaw, Catherine Heathcliff and Catherine Linton scratched into the window ledge. A fir branch has been tapping on the glass.');

const topics = [
  { id: 'english.carol', title: 'Dickens’s Scrooge: character through description', kind: 'reading', prereqs: ['english.openings'], batch: 7, intro: 'Dickens introduces Scrooge in one breathless paragraph of lists, similes and jokes. Every detail is about cold, and the cold is inside him.', teach: 'Explain how Dickens uses cold weather to describe a cold heart.', talk: 'Ask {him} which description of Scrooge {she} would use to cast an actor in a film.' },
  { id: 'english.oliver', title: 'Dickens’s satire: Oliver asks for more', kind: 'reading', prereqs: ['english.carol'], batch: 7, intro: 'Satire uses humour to attack something the writer thinks is wrong. Dickens makes us laugh at the workhouse, then feel ashamed that we laughed.', teach: 'Explain how Dickens uses irony to criticise the way the workhouse treated children.', talk: 'Ask {him} what Dickens would write about today if he were alive.' },
  { id: 'english.red-room', title: 'Jane Eyre: the red-room', kind: 'reading', prereqs: ['english.gothic'], batch: 7, intro: 'Charlotte Brontë makes an ordinary bedroom terrifying through colour, silence and a mirror. Notice that the adult Jane is telling the story of her ten-year-old self.', teach: 'Explain how Brontë uses colour to make the red-room frightening.', talk: 'Ask {him} whether the red-room is haunted, or whether Jane’s fear creates the ghost.' },
  { id: 'english.austen-wit', title: 'Austen’s dialogue: Elizabeth and Lady Catherine', kind: 'reading', prereqs: ['english.openings'], batch: 7, intro: 'Jane Austen lets dialogue do the work. Lady Catherine has wealth, rank and volume; Elizabeth has wit. Watch who controls the conversation.', teach: 'Explain how Elizabeth wins the argument while staying perfectly polite.', talk: 'Act out the scene together, with {him} as Elizabeth.' },
  { id: 'english.treasure', title: 'Treasure Island: building menace', kind: 'reading', prereqs: ['english.openings'], batch: 7, intro: 'Stevenson creates one of fiction’s most frightening villains in a few hundred words: a blind beggar with a soft voice and an iron grip.', teach: 'Explain how Stevenson uses contrast to make Pew frightening.', talk: 'Ask {him} which sound in the extract {she} would use in a film version.' },
  { id: 'english.wild', title: 'The Call of the Wild: beaten but not broken', kind: 'reading', prereqs: ['english.treasure'], batch: 7, intro: 'Jack London tells the story from a dog’s point of view. Buck learns a hard lesson about power, but keeps something the club cannot reach.', teach: 'Explain the difference between being beaten and being broken.', talk: 'Ask {him} whether Buck has learned a good lesson or a bad one.' },
  { id: 'english.magi', title: 'The twist ending: The Gift of the Magi', kind: 'reading', prereqs: ['english.short-story'], batch: 7, intro: 'O. Henry was famous for twist endings. This one is a double twist, and the narrator steps in at the end to tell us what it means.', teach: 'Explain the irony of the two Christmas presents.', talk: 'Ask {him} what {she} would sacrifice to buy a present for someone {she} loves.' },
  { id: 'english.caesar', title: 'Shakespeare’s rhetoric: Mark Antony’s funeral speech', kind: 'reading', prereqs: ['english.tempest'], batch: 7, intro: 'Antony has promised not to blame the murderers. He keeps his promise, word for word, and still turns the whole crowd against them. It is a masterclass in persuasion.', teach: 'Explain how the repetition of “Brutus is an honourable man” changes its meaning.', talk: 'Ask {him} to deliver the first eight lines as if to a real crowd.' },
  { id: 'english.blake', title: 'Blake: The Tiger and London', kind: 'reading', prereqs: ['english.war-poetry'], batch: 7, intro: 'Blake asks huge questions in short, hammering lines. “The Tiger” is built almost entirely of questions; “London” is built of cries.', teach: 'Explain what Blake means by “mind-forged manacles”.', talk: 'Ask {him} who or what {she} thinks made the tiger in Blake’s poem.' },
  { id: 'english.rossetti', title: 'Christina Rossetti: Remember and A Birthday', kind: 'reading', prereqs: ['english.blake'], batch: 7, intro: 'Two poems by the same writer, in opposite moods. One is quiet and controlled, about being remembered after death; the other bursts with colour and joy.', teach: 'Explain how the speaker’s request changes at the turn in “Remember”.', talk: 'Ask {him} which of the two poems {she} would rather have written.' },
  { id: 'english.kipling', title: 'Poems of advice: Kipling’s If—', kind: 'reading', prereqs: ['english.war-poetry'], batch: 7, intro: '“If—” is one long sentence that keeps you waiting until the final two lines for its reward. As you read, ask whether the advice still works today.', teach: 'Explain why Kipling calls Triumph and Disaster “impostors”.', talk: 'Ask {him} which line of the poem would be the best advice before an exam.' },
  { id: 'english.darwin', title: 'Scientific non-fiction: Darwin in the Galápagos', kind: 'reading', prereqs: ['english.openings'], batch: 7, intro: 'Darwin wrote for ordinary readers, not only scientists. Notice how he mixes vivid description with careful reasoning, and how honestly he admits his own mistakes.', teach: 'Explain why the different creatures on each island surprised Darwin.', talk: 'Ask {him} what Darwin would have noticed on a walk near your home.' },
  // stretch: GCSE-level texts
  { id: 'english.titania', title: 'Shakespeare’s nature imagery: Titania’s speech', kind: 'reading', tier: 'stretch', prereqs: ['english.macbeth'], batch: 7, intro: 'When the fairy king and queen quarrel, the whole natural world falls into chaos. The speech is dense with images, so read it slowly and picture each one.', teach: 'Explain how Shakespeare links a private quarrel to the disorder of the seasons.', talk: 'Ask {him} to find the most striking image in the speech and explain it.' },
  { id: 'english.ozymandias', title: 'Sonnets of the ancient world: Ozymandias and Chapman’s Homer', kind: 'reading', tier: 'stretch', prereqs: ['english.homer', 'english.sonnet'], batch: 7, intro: 'Two of the most famous sonnets in English look back at the ancient world. One finds only ruins and arrogance; the other finds a whole new world of wonder.', teach: 'Explain the irony of the words on Ozymandias’s pedestal.', talk: 'Ask {him} what ruin today might make a traveller feel as Shelley’s did.' },
  { id: 'english.wuthering', title: 'Gothic at full strength: Wuthering Heights', kind: 'reading', tier: 'stretch', prereqs: ['english.red-room'], batch: 7, intro: 'Emily Brontë’s ghost story is one of the most frightening passages in English. It is also a puzzle: a dream, a name, and twenty years of wandering.', teach: 'Explain why “Terror made me cruel” is such a shocking sentence.', talk: 'Ask {him} whether Lockwood was dreaming, and what makes {her} think so.' },
  // skills
  { id: 'english.unseen', title: 'Reading an unseen poem', kind: 'facts', prereqs: ['english.war-poetry', 'english.terms'], batch: 5, intro: 'In exams you will meet poems you have never seen. A clear method turns panic into close reading: what is happening, how it is written, and why it matters.', teach: 'Explain the steps you would take with a poem you have never read before.', talk: 'Pick a short poem neither of you knows and try the method together.' },
  { id: 'english.essay', title: 'Writing a literature essay', kind: 'facts', prereqs: ['english.terms'], batch: 5, intro: 'A top literature essay argues. It makes a clear claim, supports it with short embedded quotations, explains effects precisely, and considers more than one reading.', teach: 'Explain what makes a strong first sentence for a literature essay.', talk: 'Ask {him} to turn one of {her} written answers into an essay plan.' },
];

const items = [
  // --- A Christmas Carol
  mcq('cc.1', 'carol', '“a squeezing, wrenching, grasping, scraping, clutching, covetous, old sinner!” What is the effect of this list?', [['The words pile up so his greed seems endless', true], ['It slows the description to make Scrooge seem gentle', false, 'Every word is about seizing and holding: there is nothing gentle here.'], ['It lists the different jobs Scrooge has done', false, 'They are not jobs: they all describe greed.']], 'A long list without “and” (asyndeton) piles up words of grabbing, so Scrooge’s greed seems overwhelming.', SCROOGE),
  fact('cc.2', 'carol', 'Find and copy the simile that compares Scrooge to a sea creature.', 'solitary as an oyster', ['hard and sharp as flint', 'like a tight-fisted hand', 'as cold as ice'], 'An oyster is shut tight in its shell, just as Scrooge shuts everyone out.', { ...SCROOGE, accept: ['as an oyster', 'secret, and self-contained, and solitary as an oyster'] }),
  mcq('cc.3', 'carol', '“He carried his own low temperature always about with him.” What does Dickens suggest?', [['His coldness comes from inside him', true], ['Scrooge was often ill with a fever', false, 'A low temperature is the opposite of a fever, and it is a metaphor here.'], ['Scrooge liked winter more than summer', false, 'The point is that weather makes no difference to him at all.']], 'Dickens turns a cold heart into a literal cold that he carries everywhere: he even “iced his office in the dog-days”, the hottest days of summer.', SCROOGE),
  mcq('cc.4', 'carol', '“They often ‘came down’ handsomely, and Scrooge never did.” What is the joke?', [['A pun: the weather gives generously, Scrooge never does', true], ['Scrooge never goes downstairs to see his clerk', false, 'Think about the two meanings of “come down handsomely”.'], ['The weather is kinder than Scrooge because it is warmer', false, 'The weather is not warm. The joke is about generosity.']], 'The bad weather beats Scrooge in one way only: it gives freely.', SCROOGE),
  mcq('cc.5', 'carol', 'Why does Dickens tell us that even the blind men’s dogs pull their owners away from Scrooge?', [['Comic exaggeration: even animals sense his meanness', true], ['Scrooge had kicked the dogs in the street earlier', false, 'Nothing in the text says so. It is exaggeration for comedy.'], ['The dogs were afraid of the stick he carried', false, 'There is no stick. The dogs sense something about him.']], 'Hyperbole like this makes us laugh at Scrooge while showing how completely he has cut himself off.', SCROOGE),
  mcq('cc.6', 'carol', 'How does Scrooge feel about being avoided by everyone?', [['He enjoys it: “the very thing he liked”', true], ['He is secretly lonely and sad about it', false, 'Later in the story we may think so, but this extract says he likes it.'], ['He does not notice it at all', false, 'He notices and is pleased: “warning all human sympathy to keep its distance”.']], 'Keeping people away is “nuts” (a delight) to him. This makes his change at the end of the story all the more striking.', SCROOGE),
  written('cc.w1', 'carol', 'How does Dickens use the imagery of cold to present Scrooge? Use at least two quotations.', ['A clear point about what the cold represents', 'A quotation about his body or face', 'A quotation showing the cold is inside him', 'The effect on the reader, and a hint of what might change'], 'Dickens presents Scrooge as a man whose heart has frozen. The cold is physical: it “nipped his pointed nose” and made “his thin lips blue”, so even his body seems to have been attacked by frost. But Dickens makes it clear that this cold comes from within: he “carried his own low temperature always about with him” and “didn’t thaw it one degree at Christmas”, the season of warmth and generosity. Because no weather can affect him, the reader sees that only something extraordinary could melt him, which prepares us for the ghosts to come.', SCROOGE),

  // --- Oliver Twist
  mcq('ot.1', 'oliver', '“The bowls never wanted washing.” Why not?', [['The starving boys polished them clean', true], ['The master washed them himself each night', false, 'The next sentence explains: the boys polished them “till they shone again”.'], ['The bowls were never actually used', false, 'They were used every day, and licked clean.']], 'Dickens makes a joke out of hunger: the bowls are clean because the boys are so hungry they leave nothing.', MORE),
  mcq('ot.2', 'oliver', '“a long grace was said over the short commons.” What is the effect of this contrast?', [['Irony: a long prayer for very little food', true], ['It shows that the boys were deeply religious', false, 'Dickens is mocking the adults, not praising anyone’s faith.'], ['It tells us dinner took a long time', false, 'The gruel “disappeared” at once. Only the prayer was long.']], '“Commons” means a share of food. Long and short are set against each other to show the hypocrisy of the workhouse.', MORE),
  fact('ot.3', 'oliver', 'Find and copy the phrase that shows Oliver was frightened by his own daring.', 'somewhat alarmed at his own temerity', ['desperate with hunger, and reckless with misery', 'in stupefied astonishment', 'he turned very pale'], '“Temerity” means boldness. Oliver surprises himself.', { ...MORE, accept: ['alarmed at his own temerity'] }),
  mcq('ot.4', 'oliver', 'The tall boy hints that he might “eat the boy who slept next him”. What is Dickens’s tone here?', [['Dark comedy that makes the hunger shocking', true], ['Pure horror, with no humour at all', false, 'The phrase “a weakly youth of tender age” is mock-serious: we laugh, then wince.'], ['Admiration for the tall boy’s courage', false, 'Dickens is showing how desperate the boys have become.']], 'Dickens often makes us laugh at something terrible so that we notice it more.', MORE),
  mcq('ot.5', 'oliver', 'How does the master react to Oliver’s request?', [['He turns pale, then aims a blow at Oliver with the ladle', true], ['He laughs and gives Oliver a second helping of gruel', false, 'He is horrified, not amused.'], ['He calmly explains the workhouse rules', false, 'He “shrieked aloud for the beadle”.']], 'The reaction is absurdly out of proportion: a polite request is treated like a crime.', MORE),
  mcq('ot.6', 'oliver', 'Why is it ironic that Dickens calls Oliver “the small rebel”?', [['Asking for food is treated like a revolution', true], ['Oliver is planning to lead the boys in a riot', false, 'He was chosen by drawing lots, and he asks politely.'], ['Oliver is the tallest boy in the workhouse', false, 'He is “small”, and he is a child.']], 'Dickens exposes how cruel the system is by showing the adults’ panic at a hungry child’s request.', MORE),
  written('ot.w1', 'oliver', 'How does Dickens use humour to criticise the workhouse? Use at least two quotations.', ['A clear point about satire', 'An example of irony or exaggeration', 'The adults’ reaction', 'What Dickens wants the reader to feel and do'], 'Dickens uses humour to make his readers see how cruel the workhouse is. He jokes that “the bowls never wanted washing”, because the boys lick them clean, so the humour itself reveals their starvation. He uses irony when a “long grace” is said over “short commons”, mocking the adults who thank God for food they barely give. Finally, the master’s horror at the “small rebel” is absurd: Oliver politely asks for more, and the adults react as if he had committed a crime. Because we laugh at the adults, we are on Oliver’s side, and Dickens leaves us angry at a system that treats hungry children as criminals.', MORE),

  // --- Jane Eyre
  mcq('rr.1', 'red-room', 'Why is the red-room so seldom used?', [['Mr Reed died there', true], ['It is too small for visitors to use', false, 'It is “one of the largest and stateliest chambers in the mansion”.'], ['It is being redecorated this winter', false, 'Its secret is that Mr Reed died in it.']], '“It was in this chamber he breathed his last”: a “sense of dreary consecration” keeps people out.', REDROOM),
  fact('rr.2', 'red-room', 'Which two colours dominate the description of the room?', 'red and white', ['red and black', 'green and gold', 'blue and white'], 'Deep red curtains, carpet and cloth; the bed and chair “glared white”. Red suggests blood and passion; white suggests death and ghosts.', { ...REDROOM, ...C }),
  mcq('rr.3', 'red-room', 'The white chair looks “like a pale throne”. What is the effect?', [['It suggests a throne for a ghostly ruler', true], ['It makes the room seem cosy and welcoming', false, 'A pale throne for no one is eerie, not cosy.'], ['It shows that Jane wants to be a queen', false, 'The image is about who is missing from the room.']], 'Jane half-expects the dead Mr Reed to be present, and the throne image prepares for that fear.', REDROOM),
  mcq('rr.4', 'red-room', 'What does Jane see in the looking-glass?', [['Her own reflection, looking like a phantom', true], ['Mr Reed’s ghost standing behind her chair', false, 'It is her own “strange little figure”.'], ['Mrs Reed watching her from the doorway', false, 'Jane is alone; the figure is her reflection.']], 'The mirror makes Jane seem strange even to herself: she becomes the ghost.', REDROOM),
  mcq('rr.5', 'red-room', '“no jail was ever more secure.” What does this comparison suggest about Jane’s life at Gateshead?', [['She is a powerless prisoner in her family', true], ['She has committed a serious crime', false, 'She fought back against a bully. The prison image shows how she is treated.'], ['She feels safe and well protected there', false, '“Secure” here means locked in, not safe.']], 'Locking a ten-year-old in a dead man’s room shows how harshly the Reeds treat her.', REDROOM),
  mcq('rr.6', 'red-room', 'How can you tell that an adult Jane is telling the story?', [['She comments on her younger self, with adult words', true], ['She tells us her exact age at the start of the extract', false, 'She does not. Look at the style instead.'], ['She speaks throughout in the present tense', false, 'It is in the past tense, looking back.']], 'The older narrator explains what the child felt, which lets Brontë give us both terror and understanding.', REDROOM),
  written('rr.w1', 'red-room', 'How does Brontë make the red-room frightening? Use at least two quotations.', ['Colour and what it suggests', 'Silence, cold and the dead uncle', 'The mirror and Jane’s reflection', 'How it shows Jane’s powerlessness'], 'Brontë makes the red-room frightening by turning it into a place of death. The colour red dominates (“curtains of deep red damask”, a “crimson cloth”), suggesting blood and danger, while the bed and chair “glared white” like a corpse or a ghost. We learn that Mr Reed “breathed his last” here, so the “pale throne” seems to wait for the dead master. Most frightening of all, Jane sees her own reflection as a “strange little figure” with “glittering eyes of fear”, as if she has become a phantom. Locked in with “no jail … more secure”, she is powerless, and the room becomes a prison for a lonely child.', REDROOM),

  // --- Pride and Prejudice
  mcq('au.1', 'austen-wit', 'What does Lady Catherine claim about Mr Darcy?', [['That he is engaged to her daughter', true], ['That he has proposed to Elizabeth', false, 'She fears he might, but she claims he is engaged to her daughter.'], ['That he has lost all his money', false, 'Nothing like that is said.']], '“Mr. Darcy is engaged to my daughter.” In fact the “engagement” is only a wish of the two families.', CATHERINE),
  mcq('au.2', 'austen-wit', '“if he is so, you can have no reason to suppose he will make an offer to me.” Why is Elizabeth’s reply clever?', [['She turns Lady Catherine’s own claim against her', true], ['It is a rude insult about Lady Catherine’s daughter', false, 'It is perfectly polite. That is why it works.'], ['She admits that Darcy has already proposed', false, 'She admits nothing.']], 'Elizabeth uses logic: Lady Catherine’s visit proves that the “engagement” is not secure.', CATHERINE),
  fact('au.3', 'austen-wit', 'Find and copy the insult Lady Catherine uses for Elizabeth when she loses her temper.', 'Obstinate, headstrong girl', ['Upstart', 'Miss Bennet', 'young woman without family'], 'The insult shows that Lady Catherine has lost control of the conversation.', { ...CATHERINE, accept: ['obstinate headstrong girl', 'obstinate, headstrong girl!'] }),
  mcq('au.4', 'austen-wit', '“I will not be interrupted. Hear me in silence.” What does this show about Lady Catherine?', [['She expects to be obeyed without argument', true], ['She is shy and nervous in company', false, 'She is commanding, not shy.'], ['She is a patient and careful listener to others', false, 'She orders Elizabeth to be silent.']], 'She has already said “I have not been used to submit to any person’s whims”.', CATHERINE),
  mcq('au.5', 'austen-wit', '“He is a gentleman; I am a gentleman’s daughter; so far we are equal.” What makes this sentence powerful?', [['Its calm, balanced steps claim equality', true], ['It uses a long list of insulting words', false, 'There are no insults. Its power is its calm logic.'], ['It is a rhetorical question to Lady Catherine', false, 'It is a statement.']], 'Short balanced clauses joined by semicolons sound reasonable and final.', CATHERINE),
  mcq('au.6', 'austen-wit', 'Which best describes Elizabeth’s manner throughout?', [['Calm, polite and witty, but firm', true], ['Rude, angry and shouting', false, 'She never raises her voice. Lady Catherine is the one who loses her temper.'], ['Frightened, tearful and quiet', false, 'She stands firm: “I will make no promise of the kind.”']], 'Austen lets Elizabeth win through wit and self-respect rather than rudeness.', CATHERINE),
  written('au.w1', 'austen-wit', 'How does Austen make Elizabeth the winner of this argument? Use at least two quotations.', ['Lady Catherine’s commands and claims of rank', 'Elizabeth’s logical, polite replies', 'A moment where Lady Catherine loses control', 'Why the reader is on Elizabeth’s side'], 'Austen gives Lady Catherine all the power of rank, but lets Elizabeth win with wit. Lady Catherine commands (“Hear me in silence”) and sneers at Elizabeth’s “upstart pretensions”, yet Elizabeth replies with calm logic: if Darcy is engaged, “you can have no reason to suppose he will make an offer to me”. Her balanced sentence “He is a gentleman; I am a gentleman’s daughter; so far we are equal” sounds reasonable and unanswerable. By contrast, Lady Catherine loses control, calling her an “obstinate, headstrong girl”. The final refusal, “I will make no promise of the kind”, shows that Elizabeth’s self-respect cannot be bullied, and the reader cheers her on.', CATHERINE),

  // --- Treasure Island
  mcq('ti.1', 'treasure', '“a bitter, foggy, frosty afternoon”. How does this setting add to the atmosphere?', [['Cold and fog create a gloomy, threatening mood', true], ['It shows that the story is set in the height of summer', false, 'Frost and fog belong to winter.'], ['It has no real effect on the mood', false, 'Writers choose weather deliberately: this is pathetic fallacy.']], 'The weather matches Jim’s grief for his father and the danger approaching along the road.', PEW),
  mcq('ti.2', 'treasure', 'Pew’s first speech is polite and pitiful. Why does this make him more frightening?', [['The politeness is a mask for cruelty', true], ['It shows he is genuinely kind underneath', false, 'Moments later he threatens to break Jim’s arm.'], ['It makes him seem like a hero to Jim', false, 'His “soft-spoken” manner hides a cruel man.']], 'A villain who sounds gentle and then turns violent is more unsettling than one who shouts.', PEW),
  fact('ti.3', 'treasure', 'Find and copy the simile that describes Pew’s grip.', 'like a vise', ['like an iron fist', 'as if with age', 'like a creature'], 'A vise (or vice) is a metal clamp that holds things tight: Jim cannot escape.', { ...PEW, accept: ['like a vice', 'gripped it in a moment like a vise', 'a vise', 'vice'] }),
  mcq('ti.4', 'treasure', 'Jim calls Pew “the horrible, soft-spoken, eyeless creature”. What does the word “creature” suggest?', [['Jim sees him as barely human', true], ['Pew is a kind lover of animals', false, '“Creature” here takes away his humanity.'], ['Pew is very small and weak', false, 'The word is about monstrousness, not size.']], 'Stevenson piles up adjectives and ends with a noun that turns Pew into a monster.', PEW),
  mcq('ti.5', 'treasure', 'Why is the ending, with Pew’s stick going “tap-tap-tapping into the distance”, effective?', [['We hear him leave, and the threat lingers', true], ['It shows that Pew has been finally defeated', false, 'He leaves at his own speed, having done his business.'], ['It gives the chapter a happy ending', false, 'Jim is left standing “motionless”, shocked.']], 'Sound frames the scene: the tapping announced him and the tapping takes him away.', PEW),
  order('ti.6', 'treasure', 'Put these events in order.', ['Pew asks where he is', 'Pew grips Jim’s hand', 'Pew threatens to break Jim’s arm', 'Pew skips away into the road'], 'Polite question, iron grip, threat, then a sudden nimble exit.', PEW),
  written('ti.w1', 'treasure', 'How does Stevenson present Pew as a frightening character? Use at least two quotations.', ['His appearance', 'The contrast between his voice and his actions', 'Jim’s reactions', 'The effect of sound in the extract'], 'Stevenson makes Pew frightening through contrast. He looks pitiful, “hunched” in a “huge old tattered sea-cloak”, and speaks in an “odd sing-song” as “a poor blind man”, so we expect him to be harmless. The moment Jim helps him, the “soft-spoken, eyeless creature” grips him “like a vise” and threatens to “break your arm”: the politeness was a disguise. Jim’s fear (“I never saw in my life a more dreadful-looking figure”) makes us share his terror, and the sound of the stick going “tap-tap-tapping into the distance” leaves the threat hanging in the air long after Pew has gone.', PEW),

  // --- The Call of the Wild
  mcq('cw.1', 'wild', '“He was beaten (he knew that); but he was not broken.” What is the difference?', [['He lost the fight, but his spirit survived', true], ['He was hurt but not seriously injured', false, 'The difference is about his spirit, not his body.'], ['He won the fight in the end, after a long struggle', false, 'He was beaten: he knew that.']], 'This is the key sentence of the extract: Buck obeys, but stays himself.', CLUB),
  mcq('cw.2', 'wild', 'After the beating, the man speaks to Buck “in a genial voice”. What is the effect?', [['The friendliness after violence is chilling', true], ['It shows the man is sorry for what he did', false, 'He promises to beat Buck again if he is “a bad dog”.'], ['It makes the man seem weak and nervous', false, 'He “fearlessly patted the head”: he is completely in control.']], 'Genial means cheerful and friendly. The contrast shows how casually the man uses violence.', CLUB),
  fact('cw.3', 'wild', 'Find and copy the phrase Jack London uses for the harsh new rules Buck has discovered.', 'the reign of primitive law', ['the man in the red sweater', 'a generous meal', 'the dominion of the man'], 'Primitive law is the law of force: whoever has the club makes the rules.', { ...CLUB, accept: ['primitive law', 'reign of primitive law'] }),
  mcq('cw.4', 'wild', 'What lesson does Buck learn?', [['A man with a club must be obeyed', true], ['All men are kind if you are patient', false, 'The lesson is about power and force.'], ['He should run away at the first chance', false, 'He learns to obey, not to run.']], '“the lesson was driven home to Buck: a man with a club was a lawgiver”.', CLUB),
  mcq('cw.5', 'wild', 'Buck learns that a man with a club is “a master to be obeyed, though not necessarily conciliated”. What does “conciliated” mean here?', [['Won over or made friendly', true], ['Frightened into silence', false, 'Buck is frightened enough to obey; the point is that he need not try to win the man over.'], ['Punished for disobeying', false, 'He has been punished already. Conciliated means made friendly.']], 'Buck must obey the man with the club, but he need not try to please him or win his favour.', CLUB),
  mcq('cw.6', 'wild', 'Through whose eyes do we see the events?', [['Buck’s, though the narration is third-person', true], ['The man in the red sweater’s, in his own words', false, 'We are told what Buck “saw”, “knew” and “learned”.'], ['An unnamed first-person narrator who owns Buck', false, 'There is no “I” in this extract.']], 'Seeing the world from a dog’s viewpoint makes the cruelty of the men more striking.', CLUB),
  written('cw.w1', 'wild', 'How does Jack London show that Buck has changed? Use at least two quotations.', ['Buck’s outward obedience', 'The difference between beaten and broken', 'The idea of primitive law', 'What he keeps that the man cannot control'], 'Jack London shows that Buck has learned to obey but has not given up his spirit. Outwardly he submits: although his hair “involuntarily bristled”, he “endured it without protest” and eats “from the man’s hand”. But the narrator insists that “he was beaten … but he was not broken”, and the brackets make his defeat sound like something he simply acknowledges. The club is “his introduction to the reign of primitive law”, and he faces it “with all the latent cunning of his nature aroused”, which suggests a wilder, more dangerous Buck is waking up. He must obey the man, but need not try to please him (“not necessarily conciliated”), so the reader senses that this change is only the beginning.', CLUB),

  // --- The Gift of the Magi
  fact('gm.1', 'magi', 'How much money does Della have at the start?', 'one dollar and eighty-seven cents', ['eighty-seven dollars and one cent', 'one dollar and sixty cents', 'twenty dollars and seven cents'], 'And sixty cents of it is in pennies.', { ...MAGI, accept: ['$1.87', '1.87', '1 dollar 87 cents', 'a dollar eighty-seven'] }),
  mcq('gm.2', 'magi', 'Why does O. Henry repeat “One dollar and eighty-seven cents”?', [['It stresses how little money she has', true], ['He forgot that he had already said it', false, 'The repetition is deliberate: “Three times Della counted it.”'], ['It shows the money is slowly increasing', false, 'It stays exactly the same, which is the problem.']], 'The repetition makes us feel Della’s desperation.', MAGI),
  mcq('gm.3', 'magi', 'What has Jim bought for Della?', [['A set of tortoise-shell combs', true], ['A platinum watch chain', false, 'That is Della’s present for Jim, for his gold watch.'], ['A new winter coat and hat', false, 'The present is The Combs.']], 'Beautiful combs “just the shade to wear in the beautiful vanished hair”.', MAGI),
  mcq('gm.4', 'magi', 'Why can Jim not use Della’s present?', [['He has sold his watch to buy her combs', true], ['It is the wrong size for his watch', false, 'The problem is that the watch is gone.'], ['He does not like the colour of gold', false, 'He sold his gold watch.']], '“Give me your watch. I want to see how it looks on it.” But: “I sold the watch to get the money to buy your combs.”', MAGI),
  mcq('gm.5', 'magi', 'What is the irony of the ending?', [['Each sold a treasure to buy for the other’s', true], ['Della is angry about the present Jim gave', false, 'She hugs the combs and smiles: “My hair grows so fast, Jim!”'], ['Jim and Della discover that they are rich', false, 'They are just as poor as before.']], 'Situational irony: the gifts cancel each other out, and yet the love behind them is what matters.', MAGI),
  mcq('gm.6', 'magi', 'The narrator calls them “two foolish children” and then “the wisest”. What does he mean?', [['Their self-sacrifice is the wisest kind of love', true], ['He is simply mocking them for being silly with money', false, 'He ends by calling them the magi: wise gift-givers.'], ['He changes his mind because they were lucky', false, 'They were not lucky; they were loving.']], 'The magi were the wise men who brought gifts to the infant Jesus. The final paragraph reverses the word “foolish”.', MAGI),
  written('gm.w1', 'magi', 'How does O. Henry make the ending of the story both sad and uplifting? Use at least two quotations.', ['What is lost', 'How the characters react', 'The irony of the gifts', 'The narrator’s final judgement'], 'O. Henry’s ending is sad because both characters lose something precious for nothing: the combs were for “the beautiful vanished hair”, and Jim has sold the watch Della’s present was meant for. Yet their reactions are full of love rather than disappointment. Della hugs the combs and smiles, “My hair grows so fast, Jim!”, and Jim simply suggests they “put our Christmas presents away”. Finally the narrator steps in to reverse his own description: these “foolish children” are “the wisest” of all gift-givers, “the magi”. The irony makes the story sad, but the narrator’s voice makes it uplifting, because the real gift was their love.', MAGI),

  // --- Julius Caesar
  mcq('jc.1', 'caesar', 'What does Antony say he has come to do?', [['“to bury Caesar, not to praise him”', true], ['to accuse Brutus publicly of murder', false, 'He promised not to blame the killers, and he never openly does.'], ['to be crowned emperor in Caesar’s place', false, 'That is not what he says.']], 'He says he will not praise Caesar, and then praises him for the whole speech.', ANTONY),
  mcq('jc.2', 'caesar', 'How does the meaning of “Brutus is an honourable man” change as Antony repeats it?', [['It grows ironic as the evidence piles up', true], ['It becomes more sincere every time', false, 'Each repetition follows evidence that Brutus was wrong.'], ['It stays exactly the same throughout', false, 'The words stay the same, but their meaning changes.']], 'Repetition plus contradictory evidence turns praise into sarcasm.', ANTONY),
  mcq('jc.3', 'caesar', 'Which evidence does Antony give that Caesar was not ambitious?', [['He refused a crown three times', true], ['He was a brave soldier in battle', false, 'Antony does not mention that here.'], ['He wrote a book praising Brutus', false, 'There is no book.']], '“I thrice presented him a kingly crown, / Which he did thrice refuse: was this ambition?”', ANTONY),
  fact('jc.4', 'caesar', 'After describing the ransoms that filled Rome’s treasury, which rhetorical question does Antony ask?', 'Did this in Caesar seem ambitious?', ['What cause withholds you, then, to mourn for him?', 'Was this ambition?', 'Who is here so base that would be a bondman?'], 'Each piece of evidence is followed by a question the crowd must answer for themselves.', { ...ANTONY, ...C }),
  mcq('jc.5', 'caesar', 'Why is the pause at the end so effective?', [['It shows grief and lets the crowd react', true], ['Antony has forgotten the next lines of his speech', false, 'It is deliberate: “I must pause till it come back to me.”'], ['He wants to end the speech early', false, 'He goes on speaking afterwards.']], 'The pause appeals to emotion (pathos) and lets the citizens talk themselves round. In the next line a citizen says, “Methinks there is much reason in his sayings.”', ANTONY),
  mcq('jc.6', 'caesar', 'Antony’s points about the ransoms, the poor and the crown are mainly an appeal to…', [['logos: reason and evidence', true], ['ethos: his own good character', false, 'He does mention his friendship, but these points are evidence.'], ['pathos: pure emotion', false, 'The emotion comes at the end; these points are evidence.']], 'Antony mixes all three appeals: evidence (logos), his friendship (ethos) and his grief (pathos).', ANTONY),
  written('jc.w1', 'caesar', 'How does Antony turn the crowd against Brutus without ever saying anything directly against him? Use at least two quotations.', ['His promise and how he keeps it word for word', 'Repetition and irony', 'Evidence and rhetorical questions', 'The emotional ending'], 'Antony keeps his promise not to blame the killers, but his words do the blaming for him. He opens by claiming “I come to bury Caesar, not to praise him”, then spends the speech praising Caesar. He repeats “Brutus is an honourable man” after each piece of evidence, so the phrase becomes more ironic every time. The evidence itself is a reasoned argument: Caesar filled “the general coffers” and refused “a kingly crown” three times, followed by rhetorical questions such as “was this ambition?” that make the crowd reach their own verdict. Finally he appeals to emotion: “My heart is in the coffin there with Caesar”. By the end, the crowd believe they have decided for themselves.', ANTONY),

  // --- Blake
  mcq('bl.1', 'blake', 'How is “The Tiger” mostly built?', [['As a series of unanswered questions', true], ['As a story with a beginning, middle and end', false, 'Nothing happens: the speaker only wonders.'], ['As a list of facts about tigers', false, 'It is about who could have made the tiger.']], 'The unanswered questions create a sense of awe and fear.', BLAKE),
  mcq('bl.2', 'blake', '“What the hammer? what the chain? / In what furnace was thy brain?” How is the creator imagined here?', [['As a blacksmith at a furnace', true], ['As a gardener growing the tiger', false, 'Hammer, chain, furnace and anvil belong to a forge.'], ['As a hunter trapping the tiger', false, 'The chain and hammer are tools of making, not hunting.']], 'Like Hephaestus at his forge, the creator hammers the tiger into shape: a fearful, powerful act of making.', BLAKE),
  mcq('bl.3', 'blake', 'The first stanza asks who “Could frame” the tiger; the last asks who “Dare frame” it. Why the change?', [['It shifts from ability to daring, making the tiger more terrifying', true], ['Blake changed his mind between the first and final drafts', false, 'Changing one word in a repeated stanza is a deliberate effect.'], ['It is only there to fit the rhythm and the rhyme', false, 'Both lines end in the same word, so the change is for meaning.']], 'One word transforms the question from power to courage.', BLAKE),
  mcq('bl.4', 'blake', '“Did He who made the lamb make thee?” Why is this question so important?', [['How one creator made both gentleness and ferocity', true], ['Whether tigers in the wild really do hunt and eat lambs', false, 'The lamb is a symbol of innocence, not food.'], ['Who owns the lamb that the tiger is hunting', false, 'It is about the creator of both creatures.']], 'Blake’s Songs of Innocence contains a poem called “The Lamb”; the two poems answer each other.', BLAKE),
  mcq('bl.5', 'blake', 'In “London”, what are “mind-forged manacles”?', [['Mental chains: ideas or fears that trap people', true], ['Real handcuffs made in London’s factories', false, '“Mind-forged” tells us they are made by the mind.'], ['Jewellery worn by the rich in the city', false, 'Manacles are chains for prisoners.']], 'Blake suggests people are imprisoned by the way they think as well as by their poverty.', BLAKE),
  fact('bl.6', 'blake', 'In the first two lines of “London”, which word is repeated to suggest that even the streets and the river are owned and controlled?', 'chartered', ['wander', 'mark', 'flow'], 'A charter gives legal rights over something. Even the Thames is “chartered”.', { ...BLAKE, accept: ['charter'] }),
  written('bl.w1', 'blake', 'How does Blake create a sense of power or fear in “The Tiger” and “London”? Refer to both poems.', ['The questions and the forge imagery in “The Tiger”', 'Repetition and sound in “London”', 'One similarity between the poems', 'One difference between the poems'], 'In “The Tiger”, Blake creates awe through questions he never answers. The images of “the hammer”, “the chain” and “the furnace” make the creator a mighty blacksmith, and changing “Could frame” to “Dare frame” suggests that even making the tiger required terrifying courage. In “London” the fear is human rather than divine. Blake repeats “every” (“In every cry of every man”) so that suffering seems to be everywhere, and the “mind-forged manacles” show people trapped by their own thinking. Both poems use strong rhythm and repetition to hammer home their ideas, but “The Tiger” feels like wonder at a dangerous creation, while “London” is an angry protest about a society that has gone wrong.', BLAKE),

  // --- Rossetti
  mcq('cr.1', 'rossetti', 'In “Remember”, what is “the silent land”?', [['Death', true], ['A foreign country', false, 'She is not going abroad: she imagines being “gone away” for ever.'], ['A library', false, 'It is a gentle way of describing death.']], 'Rossetti uses a euphemism to speak about death softly.', ROSSETTI),
  mcq('cr.2', 'rossetti', 'How does the speaker’s request change after “Yet if you should forget me for a while”?', [['Better to forget her and smile than remember and be sad', true], ['She demands to be remembered even more strongly than before', false, 'Read the final couplet: “Better by far you should forget and smile”.'], ['She says that she will never, ever forget him herself', false, 'The request is about being remembered by the listener.']], 'This turn in the sonnet, the volta, changes the poem from a plea into an act of selfless love.', ROSSETTI),
  fact('cr.3', 'rossetti', 'What form is “Remember” written in?', 'a sonnet', ['a ballad', 'free verse', 'a limerick'], 'Fourteen lines of iambic pentameter, with a turn after line eight.', { ...ROSSETTI, accept: ['sonnet', 'petrarchan sonnet', 'a petrarchan sonnet'] }),
  mcq('cr.4', 'rossetti', 'The first stanza of “A Birthday” repeats “My heart is like…”. What is the effect?', [['Each repeated simile adds to her joy', true], ['They show the speaker has nothing else to say', false, 'Each simile adds a new image: a bird, a fruit tree, a shell.'], ['They make the poem sound sad and slow', false, 'The images are of song, fruitfulness and calm seas: they are joyful.']], 'Repeating the start of a line is called anaphora. Then the stanza tops all the similes: “My heart is gladder than all these”.', ROSSETTI),
  mcq('cr.5', 'rossetti', 'What does “the birthday of my life” mean?', [['The moment her life truly begins', true], ['Her actual birthday party', false, 'It is a metaphor for a new beginning.'], ['The day that she was born', false, 'It is the day love comes, not her birth.']], 'Love feels like being born again.', ROSSETTI),
  mcq('cr.6', 'rossetti', 'Which best describes the contrast between the two poems?', [['“Remember” is quiet and sad; “A Birthday” is exuberant', true], ['Both are angry protest poems about the city', false, 'Neither is a protest. One is tender, one joyful.'], ['“Remember” is joyful; “A Birthday” is about death', false, 'It is the other way round.']], 'The same poet uses form and imagery to create opposite moods.', ROSSETTI),
  written('cr.w1', 'rossetti', 'Compare how Rossetti presents love in “Remember” and “A Birthday”.', ['Love as memory and sacrifice in “Remember”', 'Love as joy and celebration in “A Birthday”', 'How form and imagery create each mood', 'A comparative conclusion'], 'In both poems love is the most important thing in the speaker’s life, but Rossetti presents it in opposite moods. In “Remember”, love is quiet and selfless. The speaker imagines death as “the silent land” and asks to be remembered, but at the turn of the sonnet she decides it is “better by far you should forget and smile / Than that you should remember and be sad”: true love puts the other person’s happiness first. In “A Birthday”, love is an explosion of joy. The repeated similes (“My heart is like a singing bird”) and the rich imagery of “silk”, “purple dyes” and “gold and silver grapes” celebrate “the birthday of my life”. One poem is restrained and sad, the other exuberant, yet both show how deeply love shapes a life.', ROSSETTI),

  // --- Kipling
  mcq('ki.1', 'kipling', 'The whole poem is one long sentence. How is it built?', [['A chain of “If” clauses, reward held to the end', true], ['A story about Kipling’s son going off to war in France', false, 'There is no story: it is advice.'], ['A conversation between two people', false, 'One voice speaks throughout.']], 'Holding back the main clause keeps the reader waiting, like the patience the poem recommends.', IF),
  mcq('ki.2', 'kipling', 'Why does Kipling call Triumph and Disaster “those two impostors”?', [['Both are temporary and deceptive', true], ['They are two villains in a story', false, 'They are personified ideas, not characters.'], ['Because winning is always bad', false, 'He says to treat them “just the same”, not that winning is bad.']], 'Capital letters personify them; calling them impostors says success and failure are both less important than they seem.', IF),
  mcq('ki.3', 'kipling', '“If you can keep your head when all about you / Are losing theirs”. Which quality does this describe?', [['Staying calm under pressure', true], ['Being good at hiding things', false, '“Keep your head” means stay calm.'], ['Being stubborn and unbending', false, 'It is about calmness while others panic.']], 'An idiom: to “lose your head” is to panic.', IF),
  mcq('ki.4', 'kipling', '“fill the unforgiving minute / With sixty seconds’ worth of distance run”. What does this mean?', [['Use every moment fully', true], ['Run a mile every single day', false, 'It is a metaphor for making the most of time.'], ['Always be in a great hurry', false, 'It is about using time well, not rushing.']], 'Time is “unforgiving”: a minute wasted cannot be won back.', IF),
  mcq('ki.5', 'kipling', 'What reward does the poem promise in its final two lines?', [['The Earth, and becoming a Man', true], ['A large fortune and a fine house', false, 'Kipling says to risk your winnings, not to pile them up.'], ['A place in heaven among the saints', false, 'Heaven is not mentioned.']], 'The reward is maturity and self-mastery rather than wealth or fame.', IF),
  mcq('ki.6', 'kipling', 'A modern reader might criticise the poem because…', [['It ties these virtues to becoming “a Man”', true], ['It is far too short to make its point', false, 'It is quite long: four eight-line stanzas.'], ['It has no regular rhyme scheme at all', false, 'It rhymes regularly.']], 'Good readers can admire a poem and still question its assumptions.', IF),
  written('ki.w1', 'kipling', 'Is “If—” still good advice for a young person today? Use the poem to support your answer.', ['A clear judgement', 'Two pieces of advice, quoted and explained', 'A limitation or criticism', 'A conclusion that weighs both sides'], '“If—” is still largely good advice, because its values do not date. Its first lines, to “keep your head when all about you / Are losing theirs”, are exactly what a student needs in an exam or an argument online. Its advice to treat Triumph and Disaster as “two impostors” warns us not to let success or failure define us, which is wise in a world of likes and grades. However, the poem assumes that these qualities make “a Man”, as if they belonged only to boys, and its demand to “never breathe a word about your loss” could encourage people to hide their feelings rather than ask for help. On balance, the poem’s calm, determined values are worth keeping, as long as we apply them to everyone and allow that strength can include talking about our struggles.', IF),

  // --- Darwin
  mcq('dw.1', 'darwin', 'How do the two tortoises react to Darwin?', [['One walks away; the other hisses and withdraws', true], ['Both of them attack him at once', false, 'Neither attacks. They are calm or defensive.'], ['They follow him all the way back down to the ship', false, 'One walks away, the other hides its head.']], 'Darwin records behaviour carefully, like a scientist, but also vividly, like a storyteller.', GALAPAGOS),
  fact('dw.2', 'darwin', 'Find and copy the word Darwin uses to say the tortoises seemed like creatures from before the great Flood of the Bible.', 'antediluvian', ['Cyclopean', 'reptiles', 'archipelago'], 'Ante = before, diluvium = flood (Latin). It makes the tortoises seem impossibly ancient.', { ...GALAPAGOS, accept: ['antediluvian animals'] }),
  mcq('dw.3', 'darwin', 'What does Darwin call “by far the most remarkable feature” of the islands?', [['Different islands have different creatures', true], ['The tortoises are extremely large', false, 'He mentions their size earlier, but the remarkable feature is the difference between islands.'], ['The islands are made almost entirely of black lava', false, 'That is the setting, not the remarkable discovery.']], 'This observation helped lead him to his theory of evolution by natural selection.', GALAPAGOS),
  mcq('dw.4', 'darwin', 'Who first pointed this out to Darwin?', [['The Vice-Governor, Mr Lawson', true], ['The captain of the Beagle', false, 'Darwin names Mr Lawson, the Vice-Governor.'], ['A local fisherman on the islands', false, 'It was the Vice-Governor.']], 'Darwin gives credit to someone else’s knowledge: good scientific practice.', GALAPAGOS),
  mcq('dw.5', 'darwin', 'Why did this surprise Darwin?', [['The islands were close and alike, yet their creatures differed', true], ['The islands were thousands of miles apart from each other', false, 'They were “about 50 or 60 miles apart, and most of them in sight of each other”.'], ['He had never seen a tortoise of any kind before then', false, 'The surprise is about the differences between islands.']], 'If conditions were the same, why were the creatures different? This question was the seed of a scientific revolution.', GALAPAGOS),
  mcq('dw.6', 'darwin', 'What does Darwin admit about his own work?', [['He partly mixed up two islands’ collections', true], ['He had lost all of his notes on the voyage', false, 'He mixed up some collections, not his notes.'], ['He never actually visited the islands himself', false, 'He describes walking among the tortoises.']], 'Admitting a mistake makes Darwin seem honest and trustworthy, which strengthens his argument.', GALAPAGOS),
  written('dw.w1', 'darwin', 'How does Darwin make his scientific writing interesting for a general reader? Use at least two quotations.', ['Vivid description of the setting and creatures', 'Personal voice and honesty', 'Building towards a surprising discovery', 'Why this makes the science convincing'], 'Darwin makes his science interesting by writing as an explorer telling a story. He describes the tortoises vividly: one “stared at me and slowly walked away”, the other “gave a deep hiss”, and among “the black lava” they seem “like some antediluvian animals”, so the reader feels transported to a strange, ancient world. He uses a personal, honest voice, admitting “I did not for some time pay sufficient attention” and that he had “partially mingled together the collections”, which makes him seem trustworthy. Finally he builds suspense, promising that “we shall soon see” why islands “in sight of each other” are “differently tenanted”. The reader is drawn into the puzzle, which makes his conclusion more exciting.', GALAPAGOS),

  // --- Titania (stretch)
  mcq('tt.1', 'titania', 'What has the quarrel between Titania and Oberon done to the human world?', [['Thrown the seasons into chaos', true], ['Brought a long, hot summer', false, 'There are fogs, floods and frosts, not heat.'], ['Nothing: it affects only the fairies', false, 'The “human mortals” suffer most.']], '“The seasons alter… the maz’d world… now knows not which is which.”', TITANIA),
  mcq('tt.2', 'titania', '“Hath every pelting river made so proud / That they have overborne their continents”. What does this mean?', [['The rivers have burst their banks', true], ['The rivers have dried up completely', false, 'They are “proud”, swollen, and overflowing.'], ['The rivers have flowed to other continents', false, '“Continents” here means the banks that contain them.']], 'The rivers are personified as proud and rebellious.', TITANIA),
  mcq('tt.3', 'titania', '“the green corn / Hath rotted ere his youth attain’d a beard”. Which technique is this?', [['Personification of the corn as a youth', true], ['Onomatopoeia imitating rotting crops', false, 'No word imitates a sound here.'], ['Alliteration on the letter “r” only', false, 'The key technique is the image of the corn as a youth.']], 'The “beard” is the whiskery head of ripe corn. The image makes the ruined harvest feel like a young death.', TITANIA),
  mcq('tt.4', 'titania', '“hoary-headed frosts / Fall in the fresh lap of the crimson rose”. What does this image show?', [['Winter invading summer', true], ['A beautiful winter garden', false, 'Frost on a summer rose is a sign of disorder.'], ['Roses that thrive in the cold', false, 'The point is that the frost should not be there.']], 'Old, white-haired winter sits in the lap of young, red summer: a disturbing contrast.', TITANIA),
  mcq('tt.5', 'titania', 'In the final lines, whom does Titania blame for the chaos?', [['Both herself and Oberon', true], ['Only Oberon, for his jealousy', false, 'She began by blaming his “brawls”, but ends with “our debate, from our dissension”.'], ['The foolish human mortals', false, 'The humans are the victims.']], 'She calls the evils their “progeny”: their children.', TITANIA),
  fact('tt.6', 'titania', 'The speech is written in unrhymed lines of ten syllables. What is this called?', 'blank verse', ['free verse', 'heroic couplets', 'prose'], 'Blank verse is unrhymed iambic pentameter, Shakespeare’s usual verse.', { ...TITANIA, accept: ['iambic pentameter', 'unrhymed iambic pentameter'] }),
  written('tt.w1', 'titania', 'How does Shakespeare use the natural world to show the effects of conflict? Use at least two quotations.', ['The link between the quarrel and the weather', 'Images of flood and ruined farming', 'The mixing of the seasons', 'Titania’s admission of blame'], 'Shakespeare shows that a quarrel between two powerful beings can throw the whole natural world into disorder. Because of their “brawls”, the winds have taken revenge, sucking up “contagious fogs” that make the rivers so “proud” they flood the fields. Farming collapses: the ploughman has “lost his sweat” and the corn has “rotted ere his youth attain’d a beard”, a personification that makes the ruined harvest feel like the death of a young man. Most strikingly, the seasons are confused, as “hoary-headed frosts / Fall in the fresh lap of the crimson rose”. When Titania finally admits “We are their parents and original”, Shakespeare suggests that conflict at the top harms everyone below.', TITANIA),

  // --- Ozymandias and Chapman's Homer (stretch)
  mcq('oz.1', 'ozymandias', 'What remains of the statue of Ozymandias?', [['Two stone legs and a broken face', true], ['The whole statue, perfectly preserved', false, 'Only “two vast and trunkless legs” and a “shattered visage” remain.'], ['Nothing at all except the sand', false, 'The legs, the face and the pedestal survive.']], 'Visage means face. Trunkless means without a body.', ANCIENT),
  mcq('oz.2', 'ozymandias', 'Why is the inscription “Look on my works, ye Mighty, and despair!” ironic?', [['Nothing remains: power fades, however great', true], ['Because the statue is still magnificent today', false, 'It is a broken wreck in an empty desert.'], ['Because Ozymandias was a modest, humble man', false, 'His “sneer of cold command” shows he was arrogant.']], 'The boast now means the opposite of what he intended: “Nothing beside remains.”', ANCIENT),
  mcq('oz.3', 'ozymandias', 'How many voices or layers stand between the reader and Ozymandias?', [['Several: poet, traveller, sculptor, then king', true], ['None: Ozymandias speaks directly to us', false, 'His words come to us through the statue, the traveller and the poet.'], ['Only one: the poet saw the statue himself', false, '“I met a traveller… Who said”.']], 'The layers make the king seem far away and long dead.', ANCIENT),
  mcq('oz.4', 'ozymandias', 'In Keats’s poem, what are “the realms of gold”?', [['The world of literature he has read', true], ['Countries rich in gold mines', false, 'It is a metaphor for reading.'], ['The kingdom of Apollo in the sky', false, 'Apollo is the god of poetry; the realms are works of literature.']], 'Keats imagines reading as travelling through kingdoms and islands.', ANCIENT),
  fact('oz.5', 'ozymandias', 'Keats compares himself to an astronomer seeing what for the first time?', 'a new planet', ['a comet', 'the Moon', 'a black hole'], 'William Herschel had discovered Uranus in 1781, within living memory when Keats wrote this sonnet.', { ...ANCIENT, accept: ['new planet', 'a planet', 'planet'] }),
  mcq('oz.6', 'ozymandias', 'Keats wrote “stout Cortez”, but the first European to see the Pacific from Darien was actually Balboa. Does the mistake matter?', [['Not to the poem: the image of wonder still works', true], ['Yes: the mistake makes the whole poem worthless', false, 'Poems are judged on more than facts. The feeling is still powerful.'], ['There is no mistake: Cortez really did see it first', false, 'Historians agree it was Balboa, in 1513.']], 'A good critic can note a factual slip and still explain why the image works.', ANCIENT),
  written('oz.w1', 'ozymandias', 'Both sonnets look back at the ancient world. Compare what each poet feels about the past.', ['What survives in “Ozymandias”, and the tone', 'What Keats discovers, and his tone', 'How each uses the sonnet form', 'A comparative judgement'], 'Both poets look back at the ancient world, but they feel very differently about it. Shelley finds only ruins: “two vast and trunkless legs of stone” and a “shattered visage”. The king’s boast, “Look on my works, ye Mighty, and despair!”, is ironic because “Nothing beside remains”, and the “lone and level sands” suggest that time defeats all human power. Keats, by contrast, finds the ancient world alive. Reading Homer makes him feel “like some watcher of the skies / When a new planet swims into his ken”, and the sonnet ends in awed silence “upon a peak in Darien”. Shelley’s sonnet is a warning about pride, while Keats’s is a celebration: one sees the past as dust, the other as a treasure that literature keeps alive.', ANCIENT),

  // --- Wuthering Heights (stretch)
  mcq('wh.1', 'wuthering', 'What does Lockwood think is making the noise at the window?', [['The fir branch tapping on the glass', true], ['A ghost knocking to be let in', false, 'He “ascribed it to the right cause”: the fir bough.'], ['The wind howling in the chimney', false, 'It is the “teasing sound” of the branch.']], 'He reaches out to stop the branch, and finds something else.', WINDOW),
  mcq('wh.2', 'wuthering', 'What do his fingers close on?', [['“a little, ice-cold hand”', true], ['The branch of the fir tree', false, 'He reaches for the branch, but grabs a hand.'], ['A piece of broken window glass', false, 'It is a cold child’s hand.']], 'The shock is sudden and physical: the ghost becomes touchable.', WINDOW),
  mcq('wh.3', 'wuthering', '“Terror made me cruel.” What does Lockwood do?', [['He cuts the ghost’s wrist on the glass', true], ['He shouts for help from the household', false, 'He does that later. First he does something cruel.'], ['He shuts the window gently and sleeps', false, 'His reaction is violent.']], 'The horror comes from Lockwood as much as from the ghost: fear turns an ordinary man savage.', WINDOW),
  mcq('wh.4', 'wuthering', '“I’ve been a waif for twenty years!” What is the effect of this line?', [['Pity for a lost child, and mystery', true], ['It makes the ghost seem threatening and evil', false, 'A “waif” is a homeless, neglected child: the line asks for pity.'], ['It tells us exactly when the ghost died', false, 'It hints, but leaves a mystery.']], 'The ghost is both frightening and pitiful, which makes the scene unsettling.', WINDOW),
  mcq('wh.5', 'wuthering', 'Why is it hard to be sure what really happened?', [['It is presented as a dream', true], ['It is written in the future tense', false, 'It is in the past tense.'], ['Lockwood admits he made it up', false, 'He never says so.']], '“The intense horror of nightmare” and “I thought, I rose” keep us unsure what was real, which makes the supernatural more disturbing.', WINDOW),
  mcq('wh.6', 'wuthering', 'Which detail is an example of pathetic fallacy?', [['“the gusty wind, and the driving of the snow”', true], ['“I muttered, knocking my knuckles through the glass”', false, 'That is an action, not weather reflecting mood.'], ['“hurriedly piled the books up in a pyramid against it”', false, 'Pathetic fallacy is weather or nature reflecting feelings.']], 'The storm outside matches the violence and fear inside.', WINDOW),
  written('wh.w1', 'wuthering', 'How does Emily Brontë create horror in this extract? Use at least two quotations.', ['The setting and the storm', 'The sudden physical shock', 'Lockwood’s own cruelty', 'Pity and mystery in the ghost’s words'], 'Brontë creates horror by mixing the supernatural with shocking human cruelty. The storm, with its “gusty wind” and “driving of the snow”, creates a wild, isolated setting. The shock comes suddenly when, reaching for a branch, Lockwood’s “fingers closed on the fingers of a little, ice-cold hand”: the ghost becomes something he can touch. Most disturbing is his reaction, “Terror made me cruel”, as he rubs the child’s wrist on the broken pane “till the blood ran down”. Yet the ghost’s cry, “I’ve been a waif for twenty years!”, makes us pity her, so the reader is caught between fear and sorrow. Because it may all be a nightmare, the horror cannot be explained away.', WINDOW),

  // --- unseen poetry (skills)
  mcq('un.1', 'unseen', 'What should you do first with a poem you have never seen?', [['Read it twice; work out speaker and situation', true], ['Count the syllables in every single line of it', false, 'Metre matters, but understanding comes first.'], ['Write down every technique you can spot', false, 'Spotting techniques without understanding leads to weak answers.']], 'Meaning first, then methods, then effects.'),
  mcq('un.2', 'unseen', 'What is “the speaker” of a poem?', [['The voice of the poem, not always the poet', true], ['The person reading the poem aloud to you', false, 'The speaker is inside the poem.'], ['Always the poet, speaking as themselves', false, 'Poets often write in other voices, like Blake’s wanderer or Rossetti’s dying lover.']], 'Say “the speaker” unless you are sure the poem is autobiographical.'),
  mcq('un.3', 'unseen', 'You notice a poem has a very regular rhyme scheme. What is the best next step?', [['Ask what effect it has, and if it breaks', true], ['Write “the poem rhymes” and move on', false, 'That describes a feature but explains nothing.'], ['Ignore it, because rhyme never matters', false, 'Form often carries meaning.']], 'A break in a pattern is often the most important moment in a poem.'),
  mcq('un.4', 'unseen', 'Which is the stronger point about structure?', [['“The final stanza shifts into the present tense, making the ending feel urgent and immediate.”', true], ['“The poem has four stanzas of equal length.”', false, 'That is a fact, not an interpretation.'], ['“The poem is written in English, in four parts.”', false, 'True, but it tells us nothing.']], 'Strong points about structure explain why a change happens.'),
  mcq('un.5', 'unseen', 'Which sentence uses a quotation best?', [['The sea is “a hungry dog”, suggesting greed and danger.', true], ['The poet says the sea is like a dog. Quote: “The sea is a hungry dog”.', false, 'Embed short quotations in your own sentence.'], ['The sea is described in lines 1 to 8, in some detail.', false, 'Point to precise words, not line ranges.']], 'Short, embedded quotations followed by an explanation are the mark of a strong answer.'),
  mcq('un.6', 'unseen', 'What does “tone” mean in a poem?', [['The attitude or feeling of the voice', true], ['How loudly the poem is read aloud', false, 'Tone is about attitude, not volume.'], ['The number of lines in each stanza', false, 'That is length, not tone.']], 'Name the tone precisely: “wistful” is better than “sad”.'),
  mcq('un.7', 'unseen', 'Why is it worth looking at a poem’s title again after reading?', [['It may gain new meaning or irony', true], ['Titles are always the least important part', false, 'Think of “Anthem for Doomed Youth”: the title is ironic.'], ['To check the spelling is correct', false, 'The point is meaning.']], '“Remember”, “London” and “If—” all gain depth once you have read the poem.'),
  mcq('un.8', 'unseen', 'An image could mean two different things. What should you do?', [['Explore both: “Alternatively, it might…”', true], ['Choose one and ignore the other completely', false, 'Examiners reward alternative interpretations.'], ['Leave the image out of your answer altogether', false, 'Ambiguity is often the most interesting thing to write about.']], 'Considering more than one reading is a sign of a confident critic.'),
  mcq('un.9', 'unseen', 'A useful order for each paragraph about a poem is…', [['What the poet says, how, and why it matters', true], ['How many lines, stanzas and rhymes it has', false, 'Counting is not analysing.'], ['The poet’s life, then the poem, then your view', false, 'Start with the poem itself.']], 'What, how, why: meaning, method and effect.'),
  mcq('un.10', 'unseen', 'Why should you pay close attention to a poem’s final line?', [['Endings often twist or unsettle the meaning', true], ['It is usually the shortest line of the poem', false, 'Length is not the point.'], ['Examiners only ever read the last line', false, 'They read your whole answer, but endings matter.']], 'Think of “Silent, upon a peak in Darien” or “They are the magi.”'),

  // --- essay writing (skills)
  mcq('es.1', 'essay', 'Which is the strongest opening sentence for an essay on how Dickens presents Scrooge?', [['Dickens presents Scrooge as frozen by greed, but able to thaw.', true], ['In this essay I am going to write about the character of Scrooge.', false, 'Announcing your topic is not an argument.'], ['Charles Dickens was born in 1812 in Portsmouth, on the south coast.', false, 'Biography is not an answer to the question.']], 'A strong thesis makes an arguable claim that the essay will prove.'),
  mcq('es.2', 'essay', 'What should a good analytical paragraph contain?', [['Point, embedded evidence, analysis and effect', true], ['As many long quotations as you can fit in', false, 'Quality of analysis matters more than quantity.'], ['A clear summary of what happens in the plot', false, 'Retelling the story is not analysing it.']], 'Point, evidence, analysis, link: and the analysis is where the marks are.'),
  mcq('es.3', 'essay', 'Which sentence uses context well?', [['Dickens, who opposed the Poor Law, makes the master’s horror absurd.', true], ['The Poor Law Amendment Act was passed in 1834, and it expanded the workhouse system.', false, 'A bare fact does not explain the text.'], ['In Victorian times life was very hard for most people.', false, 'Too vague, and not linked to the text.']], 'Context should explain a writer’s choices, not replace analysis.'),
  mcq('es.4', 'essay', 'What is usually the best length for a quotation?', [['A few precise words, embedded', true], ['A whole paragraph, copied out', false, 'Long quotations hide what you want to analyse.'], ['No quotations at all, just ideas', false, 'Evidence is essential.']], 'Short quotations let you zoom in on individual words.'),
  mcq('es.5', 'essay', 'Which phrase shows a tentative, evaluative interpretation?', [['“This perhaps suggests…”', true], ['“This definitely proves that…”', false, 'Literature rarely proves one thing. Tentative language shows thought.'], ['“This is a simile, which is…”', false, 'Identifying a technique is not interpreting it.']], 'Words like “perhaps”, “suggests” and “implies” show that you know texts can be read in more than one way.'),
  mcq('es.6', 'essay', 'What should a conclusion do?', [['Answer the question and draw the argument together', true], ['Introduce three new quotations to finish strongly', false, 'New evidence belongs in the main paragraphs.'], ['Repeat the introduction word for word to be clear', false, 'Develop your argument; don’t just repeat it.']], 'A good conclusion often makes a bigger point about the writer’s purpose.'),
  mcq('es.7', 'essay', 'Why is “This makes the reader want to read on” a weak comment?', [['It fits almost any text, so explains nothing specific', true], ['Because readers never really want to read on at all', false, 'The problem is that it is vague.'], ['Because it is far too long to be a useful comment', false, 'It is vague, not too long.']], 'Say precisely what the reader feels and why: “The delay makes us share Jim’s dread.”'),
  mcq('es.8', 'essay', 'Which sentence introduces an alternative interpretation?', [['However, a reader might also see Lockwood’s cruelty as fear.', true], ['Firstly, Brontë uses pathetic fallacy to set the mood here.', false, 'That introduces a point, not an alternative reading.'], ['In conclusion, the extract is very effective at building fear.', false, 'That is a vague conclusion.']], 'Weighing different readings is a sign of a top answer.'),
  mcq('es.9', 'essay', 'Which phrasing shows that the writer made deliberate choices?', [['“Brontë chooses the colour red to suggest…”', true], ['“The room just happens to be red.”', false, 'Nothing in a text “just happens”.'], ['“The author forgot to describe the window.”', false, 'Focus on what the writer did choose.']], 'Writing about choices keeps the focus on the writer’s methods.'),
  mcq('es.10', 'essay', 'Which tense should you usually use when writing about a text?', [['The present tense: “Dickens describes…”', true], ['The past tense: “Dickens described…”', false, 'Texts are discussed in the present because they still exist and act on readers.'], ['The future tense: “Dickens will describe…”', false, 'Use the present tense.']], 'The literary present: the text is always happening.'),
];

// --- memory hooks -------------------------------------------------------------------------
